using System.Data;using Servicio.RetazoMarket.DataManagment.Interfaces;using Servicio.RetazoMarket.DataManagment.Mappers;using Servicio.RetazoMarket.DataManagment.Models;
namespace Servicio.RetazoMarket.DataManagment.Services;public class PedidoAdministracionDataService:IPedidoAdministracionDataService {private readonly IUnitOfWork _uow;public PedidoAdministracionDataService(IUnitOfWork uow)=>_uow=uow;public async Task<PedidoDataModel> CrearAsync(PedidoDataModel model,CancellationToken ct=default){await _uow.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var entity=PedidoDataMapper.ToEntity(model);await _uow.PedidoRepository.AgregarAsync(entity,ct);await _uow.SaveChangesAsync(ct);await _uow.CommitTransactionAsync(ct);var creado=await _uow.PedidoRepository.ObtenerPorIdAsync(entity.id_pedido,ct)??throw new InvalidOperationException("No fue posible recuperar el pedido creado.");return PedidoDataMapper.ToDataModel(creado);}catch{try{await _uow.RollbackTransactionAsync(CancellationToken.None);}finally{_uow.DescartarCambios();}throw;}}public async Task<PedidoDataModel?> ActualizarPendienteAsync(PedidoDataModel model,CancellationToken ct=default){await _uow.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var entity=await _uow.PedidoRepository.ObtenerParaActualizarAsync(model.id_pedido,ct);if(entity is null||entity.estado!="PEN"){await _uow.RollbackTransactionAsync(ct);return null;}var actuales=await _uow.ProductoPedidoRepository.ObtenerPorPedidoAsync(model.id_pedido,ct);var nuevos=model.Detalles.ToDictionary(x=>x.id_producto);if(actuales.Any(x=>!nuevos.ContainsKey(x.id_producto)))throw new InvalidOperationException("No se pueden eliminar detalles de un pedido persistido.");foreach(var actual in actuales){var tracked=await _uow.ProductoPedidoRepository.ObtenerParaActualizarAsync(actual.id_producto,model.id_pedido,ct);if(tracked is null)continue;ProductoPedidoDataMapper.ApplyToEntity(nuevos[actual.id_producto],tracked);_uow.ProductoPedidoRepository.Actualizar(tracked);}foreach(var nuevo in model.Detalles.Where(x=>actuales.All(a=>a.id_producto!=x.id_producto))){var detalle=ProductoPedidoDataMapper.ToEntity(nuevo);detalle.id_pedido=entity.id_pedido;await _uow.ProductoPedidoRepository.AgregarAsync(detalle,ct);}PedidoDataMapper.ApplyToEntity(model,entity);await _uow.SaveChangesAsync(ct);await _uow.CommitTransactionAsync(ct);var actualizado=await _uow.PedidoRepository.ObtenerPorIdAsync(entity.id_pedido,ct)??throw new InvalidOperationException("No fue posible recuperar el pedido actualizado.");return PedidoDataMapper.ToDataModel(actualizado);}catch{try{await _uow.RollbackTransactionAsync(CancellationToken.None);}finally{_uow.DescartarCambios();}throw;}}}
